feedQuery:
{
    snapshot() {
      return {
        tab: currentTab,
        categoryId: currentCategoryId,
        order: currentOrder,
        period: currentPeriod,
        filter: currentFilter,
      };
    },

    key(query) {
      // 查询 key 覆盖所有会影响 API URL 或本地筛选的状态。异步请求返回时用
      // isCurrent 比较 key，丢弃用户切换视图前发出的旧响应。
      return [
        query.tab,
        query.categoryId || "",
        query.order,
        query.period,
        query.filter,
      ].join("|");
    },

    isCurrent(query) {
      return this.key(query) === this.key(this.snapshot());
    },

    buildUrl(query, page) {
      const useTopList = _usesPeriodScopedTopList(query.order, query.period);

      // Discourse 的 top 周期只在 /top.json 或分类 /l/top.json 上有完整语义。
      // period=all 的“最多浏览/回复/点赞”等排序继续走 latest.json?order=...，
      // 保留此前版本的 ranked order 行为。
      if (query.tab !== "all" && query.categoryId) {
        const categoryPath = _categoryPath(query.categoryId);
        const params = [
          `page=${page}`,
          "include_subcategories=true",
        ];
        if (useTopList) {
          params.push(`period=${encodeURIComponent(query.period)}`);
          params.push(`order=${encodeURIComponent(query.order)}`);
          return `${categoryPath}/l/top.json?${params.join("&")}`;
        }

        params.push(`order=${encodeURIComponent(query.order)}`);
        return `${categoryPath}/l/latest.json?${params.join("&")}`;
      }

      if (useTopList) {
        const params = [
          `period=${encodeURIComponent(query.period)}`,
          `order=${encodeURIComponent(query.order)}`,
          `page=${page}`,
        ];
        return `/top.json?${params.join("&")}`;
      }

      const params = [
        `order=${encodeURIComponent(query.order)}`,
        `page=${page}`,
      ];
      if (query.period !== "all" && _needsPeriodForUrl(query.order)) {
        params.push(`period=${encodeURIComponent(query.period)}`);
      }
      return `/latest.json?${params.join("&")}`;
    },
  }

functions._hasLastReadPostNumber:
function _hasLastReadPostNumber(topic) {
    return topic.last_read_post_number !== null &&
      topic.last_read_post_number !== undefined &&
      topic.last_read_post_number !== "";
  }

functions._topicListUrl:
function _topicListUrl(topic) {
    const baseUrl = _topicBaseUrl(topic);
    if (!_hasLastReadPostNumber(topic)) return baseUrl;

    const lastRead = Number(topic.last_read_post_number);
    const highest = Number(topic.highest_post_number);
    if (!Number.isFinite(lastRead)) return baseUrl;

    let postNumber = lastRead + 1;
    if (Number.isFinite(highest) && postNumber > highest) {
      postNumber = highest;
    }
    if (postNumber < 1) postNumber = 1;
    return `${baseUrl}/${postNumber}`;
  }

functions._isTopicRead:
function _isTopicRead(topic) {
    if (!topic || !topic.id) return false;
    const baseUrl = _topicBaseUrl(topic);
    const url = _topicListUrl(topic);
    return url !== baseUrl && url.startsWith(`${baseUrl}/`);
  }

functions._applyReadMarker:
function _applyReadMarker(topic) {
    topic.unread_posts = 0;
    topic.new_posts = 0;
    topic.unseen = false;
    topic.is_seen = true;
    if (topic.highest_post_number) {
      topic.last_read_post_number = topic.highest_post_number;
    }
  }

functions._trimResidentTopicsAfterRefresh:
function _trimResidentTopicsAfterRefresh() {
    const keepCount = _residentTopicLimit();

    // 异常话题停留在原位置，既不占用保留名额也不参与裁剪；它随刷新
    // 逐渐被新内容推到下方，直到全量刷新或超出异常保留上限才清除。
    const retainedTopics = [];
    const trimmedTopics = [];
    let keptCount = 0;
    for (const topic of allTopics) {
      if (topic?.sfpUnavailable) {
        retainedTopics.push(topic);
        continue;
      }
      if (keptCount < keepCount) {
        retainedTopics.push(topic);
        keptCount++;
      } else {
        trimmedTopics.push(topic);
      }
    }
    if (trimmedTopics.length === 0) return false;

    allTopics = retainedTopics;
    trimmedTopics.forEach((topic) => loadedTopicIds.delete(topic.id));
    _rebuildUsersMapForResidentTopics();
    return true;
  }

functions._rebuildUsersMapForResidentTopics:
function _rebuildUsersMapForResidentTopics() {
    const nextUsersMap = {};
    allTopics.forEach((topic) => {
      const userId = topic?.posters?.[0]?.user_id;
      if (userId !== undefined && usersMap[userId]) {
        nextUsersMap[userId] = usersMap[userId];
      }
    });
    usersMap = nextUsersMap;
  }

functions._mergeAndRenderTopics:
function _mergeAndRenderTopics(fetchedTopics, {
    mode = "prepend",
    moreTopicsUrl = "",
    incomingCandidateIds = [],
    filterTopic = null,
    clearIncomingForQuery = null,
    resetFeedDepth = true,
    sortQuery = null,
  } = {}) {
    const shouldFilterTopics = mode !== "replace-head" && typeof filterTopic === "function";
    const topics = shouldFilterTopics
      ? fetchedTopics.filter(filterTopic)
      : fetchedTopics;

    if (topics.length === 0) {
      if (incomingCandidateIds.length) _removeSidebarIncomingTopicIds(incomingCandidateIds);
      _syncIncomingHeadAction();
      return false;
    }

    const topicMap = new Map(topics.map((topic) => [topic.id, topic]));
    // 点击话题时会立即在 Resident Topic 上补已读状态，但并发刷新拿到的
    // 列表快照可能仍是未读。合并前把这份单调状态带到新对象上，避免同 id
    // 的服务器快照覆盖刚刚发生的本地点击。
    allTopics.forEach((residentTopic) => {
      const fetchedTopic = topicMap.get(residentTopic.id);
      if (fetchedTopic && _isTopicRead(residentTopic) && !_isTopicRead(fetchedTopic)) {
        _applyReadMarker(fetchedTopic);
      }
    });
    let highlightTopicIds = [];
    if (resetFeedDepth) _resetLoadedFeedDepth();

    if (mode === "replace-head") {
      highlightTopicIds = topics
        .filter((topic) => !loadedTopicIds.has(topic.id))
        .map((topic) => topic.id);
      allTopics = topics.concat(allTopics.filter((topic) => !topicMap.has(topic.id)));
      // 异常话题按排序键插回原位次，避免被整段新鲜 page-0 压出首屏。
      if (sortQuery) _interleaveUnavailableTopicsBySortKey(sortQuery, topics.length);
      hasMorePages = !!moreTopicsUrl;
    } else {
      highlightTopicIds = topics.map((topic) => topic.id);
      allTopics = topics.concat(allTopics.filter((topic) => !topicMap.has(topic.id)));
      if (resetFeedDepth) hasMorePages = allTopics.length >= Math.max(1, topicPageSize);
    }

    const newEntrantCount = topics.reduce(
      (count, topic) => (loadedTopicIds.has(topic.id) ? count : count + 1),
      0
    );
    topics.forEach((topic) => loadedTopicIds.add(topic.id));
    if (newEntrantCount > 0) _expireUnavailableTopicsByPush(newEntrantCount);
    _trimResidentTopicsAfterRefresh();

    const scrollAnchor = _captureFeedScrollAnchor();
    renderTopics(highlightTopicIds);
    if (clearIncomingForQuery) {
      _removeSidebarIncomingTopicsForQuery(clearIncomingForQuery);
    } else if (incomingCandidateIds.length) {
      _removeSidebarIncomingTopicIds(incomingCandidateIds);
    }
    _syncIncomingHeadAction();
    _restoreFeedScrollAnchor(scrollAnchor);
    _syncHeadActionState();
    return true;
  }

functions._markTopicUnavailable:
function _markTopicUnavailable(topic) {
    if (!topic || topic.sfpUnavailable) return false;
    topic.sfpUnavailable = true;
    topic.sfpUnavailablePushed = 0;
    return true;
  }

functions._expireUnavailableTopicsByPush:
function _expireUnavailableTopicsByPush(newEntrantCount) {
    if (newEntrantCount <= 0) return;

    const keepCount = _residentTopicLimit();
    const expiredIds = new Set();
    for (const topic of allTopics) {
      if (!topic?.sfpUnavailable) continue;
      topic.sfpUnavailablePushed = (topic.sfpUnavailablePushed || 0) + newEntrantCount;
      if (topic.sfpUnavailablePushed >= keepCount) expiredIds.add(topic.id);
    }
    if (expiredIds.size === 0) return;

    allTopics = allTopics.filter((topic) => !expiredIds.has(topic.id));
    expiredIds.forEach((topicId) => loadedTopicIds.delete(topicId));
    _rebuildUsersMapForResidentTopics();
  }

functions._feedSortKeyValue:
function _feedSortKeyValue(topic, order) {
    if (!topic) return null;
    switch (order) {
      case "created": {
        const created = Date.parse(topic.created_at || "");
        return Number.isFinite(created) ? created : null;
      }
      case "views":
        return Number.isFinite(topic.views) ? topic.views : null;
      case "posts":
        return Number.isFinite(topic.posts_count) ? topic.posts_count : null;
      case "likes":
        return Number.isFinite(topic.like_count) ? topic.like_count : null;
      case "op_likes":
        return Number.isFinite(topic.op_like_count) ? topic.op_like_count : null;
      case "activity":
      default: {
        const bumped = Date.parse(topic.bumped_at || "");
        return Number.isFinite(bumped) ? bumped : null;
      }
    }
  }

functions._interleaveUnavailableTopicsBySortKey:
function _interleaveUnavailableTopicsBySortKey(query, freshLength) {
    if (allTopics.length <= freshLength) return;

    const anomalies = [];
    for (let index = allTopics.length - 1; index >= freshLength; index--) {
      if (allTopics[index]?.sfpUnavailable) {
        anomalies.unshift(allTopics.splice(index, 1)[0]);
      }
    }
    if (anomalies.length === 0) return;

    // activity/default 排序中置顶会浮到头部且排序键可能很旧，插入扫描
    // 时跳过它们，避免异常话题被插到置顶块之前。
    const pinnedFloats = !query?.order || ["activity", "default"].includes(query.order);
    for (const anomaly of anomalies) {
      const keyValue = _feedSortKeyValue(anomaly, query.order);
      let insertIndex = 0;
      if (keyValue !== null) {
        while (insertIndex < allTopics.length) {
          const resident = allTopics[insertIndex];
          if (pinnedFloats && (resident.pinned || resident.pinned_globally)) {
            insertIndex++;
            continue;
          }
          const residentKey = _feedSortKeyValue(resident, query.order);
          if (residentKey !== null && residentKey < keyValue) break;
          insertIndex++;
        }
      }
      allTopics.splice(insertIndex, 0, anomaly);
    }
  }

functions._detectVanishedHeadTopics:
function _detectVanishedHeadTopics(rawTopics, query) {
    if (!Array.isArray(rawTopics) || rawTopics.length === 0) return;
    if (allTopics.length === 0) return;
    // 周期榜（top.json?period=...）按“周期内有活动”过滤成员，话题可能
    // 只因活动滚出周期而离开窗口，排序键比较会误标，因此只在 period=all
    // 的纯排序（latest.json?order=...）上检测。
    if (_needsPeriodForUrl(query.order) && query.period !== "all") return;

    const pinnedFloats = !query.order || ["activity", "default"].includes(query.order);
    const newTopicIds = new Set(
      rawTopics.map((topic) => Number(topic?.id)).filter(Number.isFinite)
    );

    let windowMinKeyValue = null;
    for (const topic of rawTopics) {
      if (pinnedFloats && (topic?.pinned || topic?.pinned_globally)) continue;
      const keyValue = _feedSortKeyValue(topic, query.order);
      if (keyValue === null) continue;
      if (windowMinKeyValue === null || keyValue < windowMinKeyValue) {
        windowMinKeyValue = keyValue;
      }
    }
    // 窗口内没有可比较的话题时无法判断，宁可漏报也不误标。
    if (windowMinKeyValue === null) return;

    // 只检查上一次 page-0 窗口内的条目；加载更多拉进来的深页条目
    // 本来就不在 page-0 语义内，缺失是正常现象。
    const candidateWindow = Math.min(rawTopics.length, allTopics.length);
    for (let index = 0; index < candidateWindow; index++) {
      const topic = allTopics[index];
      if (!topic || newTopicIds.has(Number(topic.id))) continue;
      if (pinnedFloats && (topic.pinned || topic.pinned_globally)) continue;
      if (topic.sfpUnavailable) continue;
      const keyValue = _feedSortKeyValue(topic, query.order);
      // 排序键相同（同一秒/同一计数）时顺序不确定，只用严格更新的
      // 键做判断，避免误标。
      if (keyValue === null || keyValue <= windowMinKeyValue) continue;
      _markTopicUnavailable(topic);
    }
  }

functions._resetAutoLoadState:
function _resetAutoLoadState() {
    autoLoadTimestamps = [];
    autoLoadEmptyFilterCount = 0;
    autoLoadStoppedForSession = false;
    autoLoadSessionKey = _getAutoLoadSessionKey();
  }

functions._canRunAutoLoad:
function _canRunAutoLoad() {
    _ensureAutoLoadSession();
    if (autoLoadStoppedForSession) return false;

    const now = Date.now();
    autoLoadTimestamps = autoLoadTimestamps.filter((ts) => now - ts < AUTO_LOAD_RATE_WINDOW_MS);
    return autoLoadTimestamps.length < AUTO_LOAD_MAX_REQUESTS_PER_WINDOW;
  }

functions._recordAutoLoadFilterResult:
function _recordAutoLoadFilterResult(filteredNewCount) {
    _ensureAutoLoadSession();
    if (filteredNewCount > 0) {
      autoLoadEmptyFilterCount = 0;
      return;
    }

    autoLoadEmptyFilterCount++;
    if (autoLoadEmptyFilterCount >= AUTO_LOAD_MAX_EMPTY_FILTER_RESULTS) {
      autoLoadStoppedForSession = true;
    }
  }

functions._touchSidebarIncomingTopicId:
function _touchSidebarIncomingTopicId(topicId) {
    const numericId = Number(topicId);
    if (!Number.isFinite(numericId)) return false;

    if (sidebarIncomingState.topicIdSet.has(numericId)) {
      const existingIndex = sidebarIncomingState.topicIds.indexOf(numericId);
      if (existingIndex !== -1) sidebarIncomingState.topicIds.splice(existingIndex, 1);
    } else {
      sidebarIncomingState.topicIdSet.add(numericId);
    }
    sidebarIncomingState.topicIds.push(numericId);
    sidebarIncomingState.filterStable = false;
    return true;
  }

functions._getSidebarIncomingLoadTopicIds:
function _getSidebarIncomingLoadTopicIds() {
    const loadLimit = _incomingLoadTopicLimit();
    const expectedLength = Math.min(sidebarIncomingState.filteredTopicIds.length, loadLimit);
    if (sidebarIncomingState.filteredLoadTopicIds.length !== expectedLength) {
      sidebarIncomingState.filteredLoadTopicIds = sidebarIncomingState.filteredTopicIds.length > loadLimit
        ? sidebarIncomingState.filteredTopicIds.slice(-loadLimit)
        : sidebarIncomingState.filteredTopicIds.slice();
    }
    return sidebarIncomingState.filteredLoadTopicIds.slice();
  }

functions._recomputeSidebarIncomingFilteredTopicId:
function _recomputeSidebarIncomingFilteredTopicIds(query = FeedQuery.snapshot()) {
    if (!_canUseSidebarIncomingRefresh(query)) {
      sidebarIncomingState.filteredTopicIds = [];
      sidebarIncomingState.filteredLoadTopicIds = [];
      sidebarIncomingState.filterStable = false;
      return sidebarIncomingState.filteredTopicIds;
    }

    // 这里故意只用 incoming candidate 条件，不套完整本地筛选。
    // cache 里的 payload 可能缺少 last_read_post_number/new_posts 等字段；
    // 也可能完全没有 payload。无 cache 的 id 仍要进入 apply，才能通过
    // /latest.json?topic_ids=... 补完整数据后再做最终筛选。
    const filteredTopicIds = [];
    const filteredLoadTopicIds = [];
    const loadLimit = _incomingLoadTopicLimit();
    sidebarIncomingState.topicIds.forEach((id) => {
      const topic = sidebarIncomingState.topicCache.get(Number(id));
      if (topic && !_topicMatchesIncomingCandidate(topic, query)) return;
      filteredTopicIds.push(id);
      filteredLoadTopicIds.push(id);
      if (filteredLoadTopicIds.length > loadLimit) filteredLoadTopicIds.shift();
    });
    sidebarIncomingState.filteredTopicIds = filteredTopicIds;
    sidebarIncomingState.filteredLoadTopicIds = filteredLoadTopicIds;
    return sidebarIncomingState.filteredTopicIds;
  }

functions._removeSidebarIncomingTopicIds:
function _removeSidebarIncomingTopicIds(topicIds) {
    if (!topicIds?.length) return;

    const toRemove = new Set(topicIds.map((id) => Number(id)).filter(Number.isFinite));
    if (toRemove.size === 0) return;

    sidebarIncomingState.topicIds = sidebarIncomingState.topicIds.filter((id) => !toRemove.has(Number(id)));
    sidebarIncomingState.topicIdSet = new Set(sidebarIncomingState.topicIds);
    toRemove.forEach((id) => sidebarIncomingState.topicCache.delete(Number(id)));
    _recomputeSidebarIncomingFilteredTopicIds();
  }

functions._categoryPath:
function _categoryPath(categoryId) {
    const targetCategoryId = Number(categoryId);
    if (!Number.isFinite(targetCategoryId)) return "";

    const chain = [];
    const seen = new Set();
    let meta = _getCategoryMeta(targetCategoryId);
    while (meta && !seen.has(meta.id)) {
      seen.add(meta.id);
      chain.unshift(meta);
      const parentId = Number(meta.parent_category_id);
      if (!Number.isFinite(parentId) || parentId === meta.id) break;
      meta = _getCategoryMeta(parentId);
    }

    const slugs = chain.map((cat) => cat.slug).filter(Boolean);
    if (slugs.length === 0) slugs.push("category");
    return `/c/${slugs.map((slug) => encodeURIComponent(slug)).join("/")}/${targetCategoryId}`;
  }

functions.getUiLocale:
function getUiLocale() {
    const candidates = [
      document.documentElement?.getAttribute("lang"),
      document.documentElement?.getAttribute("xml:lang"),
      getDiscourse()?.SiteSettings?.default_locale,
      navigator.language,
    ];
    const language = candidates.find((value) => String(value || "").trim()) || "en";
    return /^zh/i.test(language) ? "zh-CN" : "en";
  }

functions.t:
function t(key, params = {}) {
    const messages = I18N[getUiLocale()] || I18N.en;
    const template = messages[key] || I18N.en[key] || key;
    return String(template).replace(/\{(\w+)\}/g, (_, name) => {
      return params[name] === undefined ? `{${name}}` : String(params[name]);
    });
  }

functions.formatRelativeTime:
function formatRelativeTime(dateStr) {
    const date = new Date(dateStr);
    if (Number.isNaN(date.getTime())) return "";
    const now = new Date();
    const diff = Math.max(0, now - date);
    const seconds = Math.floor(diff / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);
    if (getUiLocale() !== "zh-CN") {
      const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
      if (seconds < 60) return rtf.format(-Math.max(1, seconds), "second");
      if (minutes < 60) return rtf.format(-minutes, "minute");
      if (hours < 24) return rtf.format(-hours, "hour");
      if (days < 30) return rtf.format(-days, "day");
      const months = Math.floor(days / 30);
      if (months < 12) return rtf.format(-months, "month");
      return rtf.format(-Math.floor(months / 12), "year");
    }
    if (seconds < 60) return `${Math.max(1, seconds)}秒前`;
    if (minutes < 60) return `${minutes}分钟前`;
    if (hours < 24) return `${hours}小时前`;
    if (days < 30) return `${days}天前`;
    const months = Math.floor(days / 30);
    if (months < 12) return `${months}个月前`;
    return `${Math.floor(months / 12)}年前`;
  }
